<script>
    const practiceList = document.getElementById('practice-question-list');
    const renumberPractice = () => [...practiceList.querySelectorAll('[data-practice-question]')].forEach((card, index) => { card.querySelector('p').textContent = `想定質問 ${index + 1}`; card.querySelectorAll('[data-practice-field]').forEach((field) => { field.name = `practice_questions[${index}][${field.dataset.practiceField}]`; }); });
    document.getElementById('add-practice-question').addEventListener('click', () => { const card = document.createElement('section'); card.dataset.practiceQuestion = ''; card.className = 'rounded-2xl bg-[#f8f1e7] p-4 sm:p-5'; card.innerHTML = '<div class="mb-3 flex items-center justify-between"><p class="text-xs font-semibold text-[#a66c48]"></p><button type="button" data-remove-practice-question class="text-xs font-semibold text-[#a94736] hover:underline">削除</button></div><label class="block text-xs font-semibold text-[#685442]">質問<textarea data-practice-field="question" maxlength="2000" rows="2" class="mt-1.5 w-full rounded-xl border border-[#e8ddce] bg-white px-3.5 py-3 text-sm font-normal leading-6"></textarea></label><label class="mt-3 block text-xs font-semibold text-[#685442]">回答メモ<textarea data-practice-field="answer" maxlength="10000" rows="4" class="mt-1.5 w-full rounded-xl border border-[#e8ddce] bg-white px-3.5 py-3 text-sm font-normal leading-6"></textarea></label>'; practiceList.append(card); renumberPractice(); });
    practiceList.addEventListener('click', (event) => { if (event.target.closest('[data-remove-practice-question]')) { event.target.closest('[data-practice-question]').remove(); renumberPractice(); } });
</script>
